import math

def get_perfect_square_products(min_factor, max_factor):
    min_square = float('inf')
    max_square = float('-inf')
    pairs = []

    k_max = int(math.isqrt(max_factor * max_factor))

    for k in range(1, k_max + 1):
        square = k * k
        if square < min_square:
            min_square = square
        if square > max_square:
            max_square = square

        root = math.isqrt(square)
        if root * root == square:
            root_square = root
            pairs.append((root, root_square))

    return (min_square, pairs, max_square)
```

