def announce_graduate(name: str, number: int, major: str) -> str:
    # Define the ordinal suffix based on the last one or two digits
    last_two = number % 100
    if 11 <= last_two <= 13:
        suffix = "th"
    else:
        last_digit = number % 10
        if last_digit == 1:
            suffix = "st"
        elif last_digit == 2:
            suffix = "nd"
        elif last_digit == 3:
            suffix = "rd"
        else:
            suffix = "th"

    return f"{name}, the {number}{suffix} graduate in {major}, please step forward."
